mapper.select:
SELECT 
    id, user_id, book_id, book_name, author, publisher, isbn, 
    original_price, price, `condition`, campus, major, course_name, 
    description, images, status, view_count, collect_count, 
    create_time, update_time, is_deleted
FROM goods
WHERE is_deleted = 0

    AND status = #{status}


    AND campus = #{campus}


    AND major = #{major}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE goods
SET view_count = view_count + 1
WHERE id = #{id}
